}", "newString": "/// Returns whether the given `function` is a nested function that is defined
/// inside a React component or hook.
///
/// A function is only considered nested when it is not itself a React component
/// or hook, but is enclosed by one. This means that React components and hooks
/// that happen to be defined inside another function (such as a test function)
/// are not considered nested, while regular functions nested inside a component
/// or hook are.
fn is_nested_function_inside_component_or_hook(function: &AnyJsFunctionOrMethod) -> bool {
    if function.is_react_component_or_hook() {
        return false;
    }

    let Some(parent) = function.syntax().parent() else {
        return false;
    };

    parent.ancestors().any(|node| {
        AnyJsFunctionOrMethod::cast(node)
            .is_some_and(|enclosing_function| enclosing_function.is_react_component_or_hook())
    })
